from collections import defaultdict

def find_regions(grid):
    """Find connected regions of non-background pixels"""
    visited = set()
    regions = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) not in visited and grid[r][c] != 0:
                region = [(r, c)]
                visited.add((r, c))

                # BFS to find all connected same-color cells
                queue = [(r, c)]
                main_color = grid[r][c]

                i = 0
                while i < len(queue):
                    cr, cc = queue[i]
                    i += 1

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if (nr, nc) not in visited and grid[nr][nc] == main_color:
                                visited.add((nr, nc))
                                region.append((nr, nc))
                                queue.append((nr, nc))

                regions.append({
                    'color': main_color,
                    'cells': region,
                    'shape': list(zip(*sorted(region)))
                })

    return regions

